changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Espagne – Hautes juridictions (Wikidata)', 'Magistrats et présidents du Tribunal constitutionnel et président du Tribunal suprême, d''après Wikidata (bloc ES-c)', 'es_pep_judiciary', 'PEP', 'https://www.wikidata.org', 'es-pep-judiciary', 'D:/test parser 2/plugins/swiftcheck-aml-es-pep-judiciary-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'SPARQL', NULL, '{"endpoint":"https://query.wikidata.org/sparql","monthsAfterEnd":"24","delayMs":"2000","kind":"positions","positions":"Q64624734 Q28518041 Q29934477","positionLabel":"{subject}","organization":"Hautes juridictions","topics":"gov.judicial gov.national","openSince":"2012-01-01"}', 168, 24, 'CC0 (Wikidata)', 'Wikidata, www.wikidata.org', 'Le Tribunal constitutionnel est protégé par un test de navigateur (non contourné) ; le CGPJ et le ministère public n''ont pas de page de composition lisible. Wikidata complète les nominations du BOE pour les titulaires nommés avant la période lue. Données collaboratives de Wikidata : un changement de titulaire non saisi n''est pas vu, à contrôler.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les magistrats du Tribunal constitutionnel décrits dans Wikidata, avec leurs dates de nomination, et le président du Tribunal.', 'Site du Tribunal constitutionnel protégé (non contourné). Wikidata peut être en retard sur un changement de composition.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-c' AND f.label LIKE 'Magistrat du Tribunal constitutionnel%' AND p.dataset_name = 'es_pep_judiciary';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Le président du Tribunal suprême décrit dans Wikidata.', 'Seulement le président : pas de liste des magistrats et présidents de chambre (poderjudicial.es sans page lisible). Contrôler la date du dernier changement de président.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-c' AND f.label LIKE 'Magistrat ou président de chambre du Tribunal suprême%' AND p.dataset_name = 'es_pep_judiciary';
